The DOM:
Reading and writing the tree, and the difference between the two node collections:

```js
const list = document.querySelector('#list');
const items = document.querySelectorAll('#list li');

console.log(items.length);              // NodeList — live-ish, forEach works
console.log([...items].map((li) => li.textContent));
console.log(list.parentElement, list.children.length, list.firstElementChild);

list.dataset.role = 'menu';             // becomes data-role="menu"
list.setAttribute('aria-expanded', 'false');
list.classList.add('open');
list.classList.toggle('open');
console.log(list.className, list.dataset.role);
```

Building nodes is safer and faster than parsing HTML, and batching writes avoids repeated layout:

```js
const frag = document.createDocumentFragment();
for (const name of ['Ana', 'Bo', 'Cy']) {
  const li = document.createElement('li');
  li.textContent = name;               // textContent escapes; innerHTML does not
  li.style.fontWeight = '600';
  frag.append(li);
}
document.querySelector('#list').append(frag);   // one layout, not three
```

The classic mistake is interleaving reads and writes, which forces the browser to lay out again each time:

```js
const rows = [...document.querySelectorAll('.row')];

// BAD: read, write, read, write...
for (const row of rows) {
  const h = row.offsetHeight;          // read -> layout
  row.style.height = `${h + 4}px`;     // write
}

// GOOD: read everything, then write everything
const heights = rows.map((row) => row.offsetHeight);
rows.forEach((row, i) => { row.style.height = `${heights[i] + 4}px`; });
```

Events:
The third argument is an options object, and `passive` and `once` are the two you actually need:

```js
element.addEventListener('click', handler, { once: true, capture: false });
element.addEventListener('wheel', onWheel, { passive: true });   // never preventDefault
window.addEventListener('scroll', onScroll, { passive: true });
const controller = new AbortController();
element.addEventListener('keydown', onKey, { signal: controller.signal });
controller.abort();                     // removes that listener
```

Delegation is what keeps a dynamic list working without re-binding:

```js
list.addEventListener('click', (event) => {
  const button = event.target.closest('button[data-id]');
  if (!button || !list.contains(button)) return;
  console.log('row', button.dataset.id);
  event.stopPropagation();              // stop it reaching an outer handler
});
```

Custom events carry data in `detail` and default to not bubbling:

```js
const picked = new CustomEvent('color:picked', {
  detail: { hex: '#ff8800' },
  bubbles: true,
});
document.addEventListener('color:picked', (e) => console.log(e.detail.hex));
document.body.dispatchEvent(picked);    // #ff8800
```

`preventDefault` cancels the browser action (navigation, form submit, context menu); `stopPropagation` stops the event travelling. They are unrelated, and confusing them is why a form sometimes submits anyway.

Networking:
`fetch` only rejects on network failure, so the status check is not optional:

```js
async function getJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  const type = res.headers.get('content-type') ?? '';
  if (!type.includes('application/json')) throw new Error(`unexpected type: ${type}`);
  return res.json();
}
```

POST with JSON, timeouts, and cancellation:

```js
const res = await fetch('/api/items', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ name: 'Ana' }),
  signal: AbortSignal.timeout(8000),
});
if (!res.ok) throw new Error(`create failed: ${res.status}`);
const created = await res.json();
```

The body is a stream and can only be read once; clone before reading twice:

```js
const r = await fetch('/api/thing');
const [a, b] = await Promise.all([r.clone().json(), r.clone().text()]);
console.log(a, b.slice(0, 20));
```

Uploads use `FormData` and never set `content-type` by hand, because the browser must add the multipart boundary:

```js
const form = new FormData();
form.append('file', fileInput.files[0]);
form.append('caption', 'holiday');
await fetch('/upload', { method: 'POST', body: form });
```

Storage in the Browser:
`localStorage` stores strings only, so everything goes through `JSON`:

```js
const save = (key, value) => localStorage.setItem(key, JSON.stringify(value));
const load = (key, fallback = null) => {
  const raw = localStorage.getItem(key);
  if (raw === null) return fallback;
  try { return JSON.parse(raw); }
  catch { return fallback; }
};

save('settings', { theme: 'dark', size: 2 });
console.log(load('settings'));           // { theme: 'dark', size: 2 }
console.log(load('missing', 'default')); // 'default'
console.log(localStorage.length);
```

Storage is per origin, survives reloads, and throws when it is full or blocked:

```js
try {
  localStorage.setItem('big', 'x'.repeat(6_000_000));
} catch (err) {
  console.log(err.name);            // QuotaExceededError
}

// Safari private mode and blocked-cookie settings can make the property throw on access
try {
  window.localStorage.setItem('k', 'v');
} catch {
  // fall back to in-memory state
}
```

`storage` fires in *other* tabs, which is how you keep two windows in sync:

```js
window.addEventListener('storage', (event) => {
  if (event.key !== 'settings') return;
  console.log('another tab changed settings to', JSON.parse(event.newValue));
});
```

`sessionStorage` has the same API but a per-tab lifetime, and `document.cookie` is the only one sent to the server — but it is limited, string-only, and must be `Secure` and `HttpOnly` when it holds a session.

Modern Browser APIs:
`IntersectionObserver` replaces scroll maths for lazy loading and reveal effects:

```js
const io = new IntersectionObserver((entries) => {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    entry.target.classList.add('visible');
    io.unobserve(entry.target);            // one-shot
  }
}, { rootMargin: '0px 0px -10% 0px', threshold: 0.1 });

document.querySelectorAll('.card').forEach((el) => io.observe(el));
```

`requestAnimationFrame` is the only correct place to animate, and it is throttled to the display:

```js
let x = 0;
function frame() {
  x += 2;
  box.style.transform = `translateX(${x}px)`;
  if (x < 200) requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
```

Media queries, clipboard and visibility all have first-class APIs:

```js
const dark = window.matchMedia('(prefers-color-scheme: dark)');
console.log(dark.matches);
dark.addEventListener('change', (e) => console.log('now dark?', e.matches));

await navigator.clipboard.writeText('copied');
console.log(await navigator.clipboard.readText());

document.addEventListener('visibilitychange', () => {
  console.log(document.hidden ? 'hidden' : 'visible');
});
```

`ResizeObserver` and `AbortSignal` round out the set: the first reports element size without a window resize, and the second cancels any listener or fetch in one call.

Node.js Fundamentals:
A command-line program is `process.argv` plus an exit code:

```js
#!/usr/bin/env node
const [, , ...args] = process.argv;
const flags = Object.fromEntries(
  args.filter((a) => a.startsWith('--')).map((a) => a.replace(/^--/, '').split('=')),
);
console.log(args, flags);
process.exitCode = args.length ? 0 : 1;
```

Environment variables are strings or undefined, and everything else is a conversion you must make:

```js
const port = Number(process.env.PORT ?? 3000);
const debug = process.env.DEBUG === 'true';
if (!Number.isInteger(port)) {
  console.error('PORT must be an integer');
  process.exit(1);
}
console.log({ port, debug, node: process.version, pid: process.pid });
```

In an ES module there is no `__dirname`; you derive it from the module URL:

```js
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const asset = resolve(here, '..', 'data', 'cities.json');
console.log(here, asset, join(here, '..', 'data'));
```

Graceful shutdown is a signal handler plus a flag, so a second signal can escalate:

```js
let stopping = false;
for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, () => {
    if (stopping) process.exit(1);
    stopping = true;
    console.log('closing...');
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(1), 5000).unref();
  });
}
```

Files, Streams and Buffers:
The promise API covers most work, and `withFileTypes` saves a stat per entry:

```js
import { readFile, writeFile, readdir, stat, mkdir } from 'node:fs/promises';

await mkdir('out', { recursive: true });
await writeFile('out/a.txt', 'hello\n', 'utf8');
const text = await readFile('out/a.txt', 'utf8');
console.log(text.trim());

const entries = await readdir('out', { withFileTypes: true });
console.log(entries.map((e) => `${e.isDirectory() ? 'dir' : 'file'}:${e.name}`));
const info = await stat('out/a.txt');
console.log(info.size, info.mtime.toISOString());
```

The async iterable form of a stream reads a large file with constant memory:

```js
import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';

await pipeline(
  createReadStream('big.log'),
  createGzip(),
  createWriteStream('big.log.gz'),
);
```

Buffers are byte arrays with encodings, and the conversion direction matters:

```js
const buf = Buffer.from('héllo', 'utf8');
console.log(buf.length, buf.toString('hex').slice(0, 8), buf.toString('utf8'));
console.log(Buffer.from(buf.toString('base64'), 'base64').toString('utf8'));
console.log(Buffer.byteLength('héllo'));   // 6, not .length 5
console.log(buf.subarray(0, 2));           // shares memory with buf
```

Always prefer `pipeline` over `.pipe()`: it forwards errors, destroys every stream on failure, and returns a promise you can await.

npm, Packages and Semver:
The fields that change how a package behaves:

```json
{
  "type": "module",
  "exports": {
    ".": { "types": "./dist/index.d.ts", "import": "./dist/index.js" }
  },
  "bin": { "mytool": "./dist/cli.js" },
  "files": ["dist"],
  "engines": { "node": ">=22" },
  "peerDependencies": { "react": "^18" },
  "sideEffects": false
}
```

Version ranges are carets, tildes and wildcards, and the difference is what you are promising:

```js
// ^1.2.3  allows 1.x.x but not 2.0.0   — the usual default
// ~1.2.3  allows 1.2.x but not 1.3.0   — tighter
// 1.2.x   allows 1.2.*
// *       anything
// 1.2.3   exactly, no range

// sorting obeying semver precedence (1.10.0 > 1.9.0)
const versions = ['1.9.0', '1.10.0', '1.2.3-alpha.1', '1.2.3'];
versions.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
console.log(versions);
```

Scripts are the documented entry points, and `npm` lifecycle order is what makes them reliable:

```json
{
  "scripts": {
    "build": "vite build",
    "test": "vitest run",
    "prepublishOnly": "npm run build && npm test"
  }
}
```

Lockfiles pin the whole tree; commit them. `npm ci` installs exactly the lockfile, while `npm install` may update it.

Testing and Quality:
A test is an assertion plus a name. This is a complete runner in fifteen lines:

```js
const tests = [];
const test = (name, fn) => tests.push({ name, fn });
const assertEqual = (actual, expected, msg = '') => {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${msg}\n  expected ${e}\n  actual   ${a}`);
};

test('adds', () => assertEqual(add(1, 2), 3));
test('rejects negatives', () => {
  let threw = false;
  try { add(-1, 1); } catch { threw = true; }
  assertEqual(threw, true);
});

let failed = 0;
for (const t of tests) {
  try { t.fn(); console.log('ok  ', t.name); }
  catch (err) { failed++; console.log('FAIL', t.name, err.message); }
}
console.log(failed ? `${failed} failing` : 'all passing');
```

Table-driven tests express a rule once and cover the edges explicitly:

```js
const cases = [
  [0, 'zero'],
  [1, 'positive'],
  [-1, 'negative'],
  [Number.NaN, 'unknown'],
];
for (const [input, expected] of cases) {
  assertEqual(describe(input), expected, `describe(${input})`);
}
```

Time and randomness are the two things that make tests flaky, so inject them:

```js
function makeClock(now) {
  let t = now;
  return { now: () => t, advance: (ms) => (t += ms) };
}

const clock = makeClock(0);
clock.advance(1500);
console.log(clock.now());            // 1500 — deterministic, no timers needed
```

Test behaviour through the public surface, and assert on values rather than on log output. A test that reaches into internals locks in the implementation and fails on every refactor.

Bundlers, Linters and Transpilers:
A bundler is configured by what it must replace, split and target:

```js
// vite.config.js
export default defineConfig({
  define: { __BUILD_ID__: JSON.stringify(process.env.GIT_SHA ?? 'dev') },
  build: {
    outDir: 'dist',
    sourcemap: true,
    target: 'es2022',
    rollupOptions: { output: { manualChunks: { vendor: ['react', 'react-dom'] } } },
  },
});
```

Dynamic import is the only reliable code-splitting signal; the bundler cannot see a static one:

```js
// one chunk, always downloaded
import { heavy } from './heavy.js';

// a separate chunk, fetched on demand
const { heavy } = await import('./heavy.js');

// route-level splitting with a name the bundler can see
const Page = (await import('./pages/Account.js')).default;
```

Linting catches the mistakes a type system cannot express:

```json
{
  "rules": {
    "no-floating-promises": "error",
    "no-unused-vars": "warn",
    "eqeqeq": ["error", "always", { "null": "ignore" }],
    "no-restricted-globals": ["error", "event", "name"]
  }
}
```

Transpilation is a target decision. If you must ship to an older runtime, pick the target and let the tool pick the transforms — hand-written polyfills for syntax features (like spread) are almost always slower than the transpiled output, and `core-js`-style runtime polyfills for APIs cannot be added for you.

Design Patterns in JavaScript:
The module singleton is the only singleton you need, because the module registry already guarantees one instance:

```js
// config.js
const config = { api: '/api', retries: 3 };
export default Object.freeze(config);
```

Factory functions hide construction and make testing easy:

```js
const createUser = ({ id, name, role = 'viewer' }) => ({
  id, name, role,
  can(action) { return RIGHTS[role].includes(action); },
  toJSON() { return { id, name, role }; },
});
const RIGHTS = { viewer: ['read'], editor: ['read', 'write'], admin: ['read', 'write', 'delete'] };
console.log(createUser({ id: 1, name: 'Ana' }).can('write'));   // false
```

The strategy pattern is a function-valued property, and the observer pattern is a Set of callbacks:

```js
const pricing = {
  flat: () => 100,
  weight: (kg) => kg * 4,
  free: () => 0,
};
const price = (mode, ...args) => (pricing[mode] ?? pricing.flat)(...args);
console.log(price('weight', 9), price('nope'));    // 36 100

const listeners = new Set();
const subscribe = (fn) => { listeners.add(fn); return () => listeners.delete(fn); };
const publish = (value) => listeners.forEach((fn) => fn(value));
const off = subscribe(console.log);
publish('changed');
off();
```

A repository interface keeps storage out of the domain, and it is a plain object of functions:

```js
const memoryRepo = () => {
  const rows = new Map();
  return {
    get: (id) => rows.get(id),
    put: (row) => void rows.set(row.id, row),
    all: () => [...rows.values()],
  };
};
```

Functional Programming:
A pure function depends only on its arguments and changes nothing outside itself:

```js
const addItem = (cart, item) => [...cart, item];                 // pure
const addItemMutating = (cart, item) => { cart.push(item); return cart; };  // not

const cart = [{ id: 1 }];
const next = addItem(cart, { id: 2 });
console.log(cart.length, next.length);    // 1 2
```

Immutable updates of nested structures are a spread chain, and it is worth naming them:

```js
const state = { user: { name: 'Ana', tags: ['a'] }, count: 0 };
const updated = {
  ...state,
  user: { ...state.user, tags: [...state.user.tags, 'b'] },
  count: state.count + 1,
};
console.log(state.user.tags, updated.user.tags);   // ['a'] ['a','b']
```

Higher-order functions compose into pipelines, and the order of `filter` before `map` matters for cost:

```js
const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);

const activeNames = pipe(
  (rows) => rows.filter((r) => r.active),
  (rows) => rows.map((r) => r.name.trim()),
  (names) => [...new Set(names)].sort(),
);
console.log(activeNames([{ name: ' bo ', active: true }, { name: 'ana', active: false }, { name: 'bo', active: true }]));
// [ 'bo' ]
```

Folding is where functional style earns its keep, and it replaces every loop you would otherwise write:

```js
const orders = [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }, { sku: 'a', qty: 3 }];
const bySku = orders.reduce((acc, o) => {
  acc[o.sku] = (acc[o.sku] ?? 0) + o.qty;
  return acc;
}, Object.create(null));
console.log(bySku);      // { a: 5, b: 1 }
```

Memory, Performance and Profiling:
Measure with a high-resolution clock and a warm-up, or you measure the JIT:

```js
const bench = (label, fn, iterations = 100_000) => {
  fn();                                     // warm up
  const start = performance.now();
  for (let i = 0; i < iterations; i++) fn();
  const ms = performance.now() - start;
  console.log(`${label}: ${ms.toFixed(1)}ms total, ${(ms / iterations * 1000).toFixed(0)}ns/op`);
};

bench('includes', () => [1, 2, 3].includes(2));
```

An accidental quadratic is the most common real defect, and a Set removes it:

```js
const allowed = new Set([...Array(20_000).keys()]);
const rows = [...Array(20_000).keys()].map((n) => ({ n }));

const slow = (list) => list.filter((row) => [...allowed].includes(row.n));  // O(n*m)
const fast = (list) => list.filter((row) => allowed.has(row.n));            // O(n)
console.log(fast(rows).length === slow(rows).length);
```

Allocation per item is what turns a loop hot. Reuse the accumulator:

```js
// allocates an array per row
const out = rows.map((r) => `#${r.n}`).join('|');

// one buffer, one pass
let acc = '';
for (const r of rows) acc += `|#${r.n}`;
console.log(out.length, acc.length);
```

To find out where time really goes, capture a profile rather than guessing: `node --cpu-prof app.js` writes a `.cpuprofile` that the DevTools Performance panel opens, and the widest frame at the deepest level is the leaf that owns the time. For the event loop, `monitorEventLoopDelay` reports the delay histogram — a p99 above tens of milliseconds means something synchronous is hogging the thread.

Security:
Escaping must happen at the moment of insertion into the right context, never earlier:

```js
const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[c]);

// safe: textContent does not parse HTML
element.textContent = userInput;

// safe: an attribute value, escaped
el.setAttribute('title', escapeHtml(userInput));

// NEVER: a URL built by concatenation
// el.href = `/go?url=${userInput}`;
```

Allow-list outbound URLs before using them in a link or a redirect, and parse rather than pattern-match:

```js
const SAFE_PROTOCOLS = new Set(['https:', 'mailto:']);
function safeUrl(input, base = location.origin) {
  let url;
  try { url = new URL(input, base); }
  catch { return null; }
  return SAFE_PROTOCOLS.has(url.protocol) ? url.toString() : null;
}
console.log(safeUrl('https://example.com/a'));
console.log(safeUrl('javascript:alert(1)'));     // null
console.log(safeUrl('  JaVaScRiPt:alert(1)'));   // null
```

Never build queries or commands from strings:

```js
// SQL: parameters, always
db.query('SELECT * FROM users WHERE email = ? AND active = ?', [email, 1]);
// WRONG: db.query(`SELECT * FROM users WHERE email = '${email}'`);

// shell: an argument array, never a string
Bun.spawn(['convert', inputPath, '-resize', '200x200', outputPath]);
// WRONG: exec(`convert ${inputPath} -resize 200x200 ${outputPath}`)
```

Passwords are hashed with a slow, salted algorithm and compared in constant time; path traversal is stopped by resolving and checking the prefix, not by stripping dots; and `eval`, `new Function` and `innerHTML` with untrusted data are all code execution.

Metaprogramming:
A `Proxy` intercepts operations, and `Reflect` is the default behaviour you fall back to:

```js
const logged = (target, label) => new Proxy(target, {
  get(obj, prop, receiver) {
    const value = Reflect.get(obj, prop, receiver);
    if (typeof value === 'function') return (...args) => {
      console.log(`${label}.${String(prop)}(${args.join(', ')})`);
      return value.apply(obj, args);
    };
    return value;
  },
  set(obj, prop, value) {
    if (typeof value !== 'number') throw new TypeError(`${String(prop)} must be a number`);
    return Reflect.set(obj, prop, value);
  },
});

const counter = logged({ n: 0, inc() { this.n += 1; return this.n; } }, 'counter');
console.log(counter.inc());
// counter.inc()
// 1
// counter.n = 'x';          // TypeError
```

Well-known symbols let your objects participate in the language:

```js
class Matrix {
  constructor(rows) { this.rows = rows; }
  get [Symbol.toStringTag]() { return 'Matrix'; }
  [Symbol.toPrimitive]() { return this.rows.flat().join(','); }
}
const m = new Matrix([[1, 2], [3, 4]]);
console.log(`${m}`, Object.prototype.toString.call(m));
// 1,2,3,4 [object Matrix]
```

Property inspection is reflection, and it is the honest way to write a generic serializer:

```js
function describe(obj) {
  return Object.entries(obj)
    .map(([k, v]) => `${k}=${v}`)
    .join(' & ');
}
console.log(describe({ a: 1, b: 'x' }));
console.log(Object.getOwnPropertyNames(describe));
```

Metaprogramming has a real cost: proxies deoptimise property access, getters hide work behind syntax, and code that reads its own structure is hard to type-check. Reach for it when a library boundary genuinely needs it, not to save a few lines.
